{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.store_replen_4_May2025 as Select * from ( With exclude as ( Select * from ( WITH warehouse_rank AS ( SELECT facility, REPLACE( REPLACE( REPLACE(UPPER(SKU),\'-48\',\'-7XL\'), \'-50\',\'-8XL\'), \'-XXXL\', \'-3XL\') AS SKU, CASE WHEN units_on_hand <=1 THEN 0 ELSE units_on_hand -1 END AS units_on_hand, ROW_NUMBER() OVER (PARTITION BY SKU ORDER BY units_on_hand DESC) AS warehouse_rank FROM SNITCH_DB.MAPLEMONK.LIVE_INV_WAREHOUSE_offline_replen ), replen_requirements AS ( SELECT SKU_CODE, branch_code, final_action, pareto, priority, REPLEN_UNITS, REPLEN_UNITS as total_replen_req, ROW_NUMBER() OVER (PARTITION BY SKU_CODE ORDER BY pareto,priority ASC) AS replen_order FROM snitch_db.maplemonk.store_replen_3_May2025 ), warehouse_1 AS ( SELECT r.SKU_CODE, r.branch_code, r.final_action, r.pareto, r.priority, r.REPLEN_UNITS, r.total_replen_req, w.facility, w.units_on_hand, r.replen_order, CASE WHEN r.REPLEN_UNITS <= w.units_on_hand THEN r.REPLEN_UNITS ELSE w.units_on_hand END AS allocated_units, CASE WHEN r.REPLEN_UNITS <= w.units_on_hand THEN 0 ELSE r.REPLEN_UNITS - w.units_on_hand END AS remaining_units FROM replen_requirements r JOIN warehouse_rank w ON r.SKU_CODE = w.SKU AND w.warehouse_rank = 1 ), warehouse_2 AS ( SELECT r.SKU_CODE, r.branch_code, r.final_action, r.pareto, r.priority, r.total_replen_req, w.facility, w.units_on_hand, r.replen_order, CASE WHEN r.REPLEN_UNITS <= w.units_on_hand THEN r.REPLEN_UNITS ELSE w.units_on_hand END AS allocated_units, CASE WHEN r.REPLEN_UNITS <= w.units_on_hand THEN 0 ELSE r.REPLEN_UNITS - w.units_on_hand END AS remaining_units FROM (SELECT SKU_CODE, branch_code, final_action, pareto, priority, remaining_units AS REPLEN_UNITS, total_replen_req, replen_order FROM warehouse_1 WHERE remaining_units > 0) r JOIN warehouse_rank w ON r.SKU_CODE = w.SKU AND w.warehouse_rank = 2 ), warehouse_3 AS ( SELECT r.SKU_CODE, r.branch_code, r.final_action, r.pareto, r.priority, w.facility, w.units_on_hand, r.replen_order, r.total_replen_req, CASE WHEN r.REPLEN_UNITS <= w.units_on_hand THEN r.REPLEN_UNITS ELSE w.units_on_hand END AS allocated_units, CASE WHEN r.REPLEN_UNITS <= w.units_on_hand THEN 0 ELSE r.REPLEN_UNITS - w.units_on_hand END AS remaining_units FROM (SELECT SKU_CODE, branch_code, final_action, pareto, priority, remaining_units AS REPLEN_UNITS, total_replen_req, replen_order FROM warehouse_2 WHERE remaining_units > 0) r JOIN warehouse_rank w ON r.SKU_CODE = w.SKU AND w.warehouse_rank = 3 ), warehouse_4 AS ( SELECT r.SKU_CODE, r.branch_code, r.final_action, r.pareto, r.priority, r.total_replen_req, w.facility, w.units_on_hand, r.replen_order, CASE WHEN r.REPLEN_UNITS <= w.units_on_hand THEN r.REPLEN_UNITS ELSE w.units_on_hand END AS allocated_units, CASE WHEN r.REPLEN_UNITS <= w.units_on_hand THEN 0 ELSE r.REPLEN_UNITS - w.units_on_hand END AS remaining_units FROM (SELECT SKU_CODE, branch_code, final_action, pareto, priority, remaining_units AS REPLEN_UNITS, total_replen_req, replen_order FROM warehouse_3 WHERE remaining_units > 0) r JOIN warehouse_rank w ON r.SKU_CODE = w.SKU AND w.warehouse_rank = 4 ), all_allocations AS ( SELECT SKU_CODE, branch_code, final_action, pareto, priority, facility, allocated_units, units_on_hand, total_replen_req, replen_order FROM warehouse_1 UNION ALL SELECT SKU_CODE, branch_code, final_action, pareto, priority, facility, allocated_units, units_on_hand, total_replen_req, replen_order FROM warehouse_2 UNION ALL SELECT SKU_CODE, branch_code, final_action, pareto, priority, facility, allocated_units, total_replen_req, units_on_hand, replen_order FROM warehouse_3 UNION ALL SELECT SKU_CODE, branch_code, final_action, pareto, priority, facility, allocated_units, total_replen_req, units_on_hand, replen_order FROM warehouse_4 ), final_check AS ( SELECT SKU_CODE, branch_code, final_action, pareto, priority, facility, allocated_units, total_replen_req, replen_order, SUM(allocated_units) OVER (PARTITION BY SKU_CODE, facility ORDER BY replen_order) AS cumulative_allocated_units, units_on_hand FROM all_allocations ) SELECT SKU_CODE, branch_code, final_action, pareto, priority, facility, replen_order, total_replen_req, CASE WHEN cumulative_allocated_units <= units_on_hand THEN allocated_units ELSE 0 END AS allocated_units FROM final_check WHERE allocated_units > 0 ORDER BY SKU_CODE, branch_code, facility) ), List_1 as ( Select * from ( SELECT *, ROW_NUMBER() OVER (PARTITION BY \"Branch code\", \"SKU GROUP\" ORDER BY \"Branch code\") AS row_num FROM snitch_db.maplemonk.exclude_list ) where row_num = 1) Select a.*, b.\"SKU GROUP\" from exclude a left join List_1 b on REVERSE(SUBSTRING(REVERSE(REPLACE(a.SKU_CODE, \'\"\', \'\')), POSITION(\'-\' IN REVERSE(REPLACE(a.SKU_CODE, \'\"\', \'\'))) + 1)) = TRIM(b.\"SKU GROUP\") and a.branch_code =b.\"Branch code\" ) where \"SKU GROUP\" is null ; create or replace table snitch_db.maplemonk.store_replen_4_Nov2025 as WITH rpl_3 AS ( SELECT * FROM snitch_db.maplemonk.store_replen_3_May2025 ), ranked_stores AS ( SELECT BRANCH_CODE_PRIORITY, short_name AS region FROM SNITCH_DB.MAPLEMONK.GOOGLE_SHEET_FRESH_PRIORITY ), warehouse_stock AS ( SELECT * FROM SNITCH_DB.MAPLEMONK.LIVE_INV_WAREHOUSE_offline_replen WHERE units_on_hand > 1 ), warehouse_preference AS ( SELECT r.SKU_CODE, r.branch_code, r.REPLEN_UNITS, rs.region, r.PRIORITY, w.facility, w.units_on_hand, CASE WHEN rs.region = \'North\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 1 WHEN rs.region = \'North\' AND w.facility <> \'SAPL-NORTH-TAURU\' THEN 2 WHEN rs.region = \'South\' AND w.facility <> \'SAPL-NORTH-TAURU\' THEN 1 WHEN rs.region = \'South\' AND w.facility = \'SAPL-NORTH-TAURU\' THEN 2 ELSE 3 END AS base_priority FROM rpl_3 r JOIN warehouse_stock w ON r.SKU_CODE = w.SKU LEFT JOIN ranked_stores rs ON r.branch_code = rs.BRANCH_CODE_PRIORITY ), ordered_warehouses AS ( SELECT *, ROW_NUMBER() OVER( PARTITION BY SKU_CODE, branch_code ORDER BY base_priority ASC, units_on_hand DESC, facility ) AS warehouse_order FROM warehouse_preference ), allocation_base AS ( SELECT o.SKU_CODE, o.branch_code, o.PRIORITY, o.region, o.facility, o.warehouse_order, o.REPLEN_UNITS, o.units_on_hand, o.base_priority, COALESCE( SUM(o.REPLEN_UNITS) OVER( PARTITION BY o.SKU_CODE, o.facility ORDER BY o.base_priority ASC, o.PRIORITY ASC, o.branch_code ASC, o.warehouse_order ASC ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ), 0 ) AS cum_req_before_fac, (o.units_on_hand - COALESCE( SUM(o.REPLEN_UNITS) OVER( PARTITION BY o.SKU_CODE, o.facility ORDER BY o.base_priority ASC, o.PRIORITY ASC, o.branch_code ASC, o.warehouse_order ASC ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ), 0 ) ) AS remaining_facility_before FROM ordered_warehouses o ), allocation_with_stop AS ( SELECT a.*, GREATEST(LEAST(a.remaining_facility_before, a.REPLEN_UNITS), 0) AS allocatable_here, COALESCE( SUM(GREATEST(LEAST(remaining_facility_before, REPLEN_UNITS), 0)) OVER ( PARTITION BY SKU_CODE, branch_code ORDER BY base_priority ASC, units_on_hand DESC, facility ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ), 0 ) AS cum_allocatable_before_store FROM allocation_base a ), final_rpl_4 as ( SELECT SKU_CODE, branch_code, region, PRIORITY, facility, warehouse_order, REPLEN_UNITS, units_on_hand, base_priority, LEAST( GREATEST(REPLEN_UNITS - cum_allocatable_before_store, 0), GREATEST(allocatable_here, 0) ) AS allocated_units FROM allocation_with_stop WHERE LEAST( GREATEST(REPLEN_UNITS - cum_allocatable_before_store, 0), GREATEST(allocatable_here, 0) ) > 0 ORDER BY SKU_CODE, base_priority, PRIORITY, branch_code, warehouse_order), exclusion_list as ( SELECT *, ROW_NUMBER() OVER (PARTITION BY \"Branch code\", \"SKU GROUP\" ORDER BY \"Branch code\") AS row_num FROM snitch_db.maplemonk.exclude_list ), exclusion as ( SELECT a.*, b.\"SKU GROUP\" FROM final_rpl_4 a LEFT JOIN exclusion_list b ON a.branch_code = b.\"Branch code\" AND CASE WHEN a.sku_code LIKE \'%-%\' THEN REGEXP_REPLACE(a.sku_code, \'-[^-]*$\', \'\') ELSE a.sku_code END = TRIM(b.\"SKU GROUP\") WHERE b.\"SKU GROUP\" IS NULL) select SKU_CODE, BRANCH_CODE, Region, Facility, replen_units as \"TOTAL_REPLEN_REQ\", ALLOCATED_UNITS from exclusion; CREATE OR REPLACE TABLE snitch_db.maplemonk.SRU_RPL_4_MARCH_26 AS WITH base AS ( SELECT * FROM snitch_db.maplemonk.SRU_RPL_3_MARCH_26 ), unpivoted AS ( SELECT branch_code, zone, sku_group, category, AVG_SKU_SELL_THRU, final_rank, size_unpivot, replen_units FROM base UNPIVOT ( replen_units FOR size_unpivot IN ( RPL_UNITS_XS, RPL_UNITS_S, RPL_UNITS_M, RPL_UNITS_L, RPL_UNITS_XL, RPL_UNITS_XXL, RPL_UNITS_3XL, RPL_UNITS_4XL, RPL_UNITS_5XL, RPL_UNITS_6XL ) ) ), mapped AS ( SELECT branch_code, zone, sku_group, category, AVG_SKU_SELL_THRU, size_unpivot, CASE WHEN category IN ( \'Blazers\',\'Hoodies\',\'Jackets\',\'Overshirt\',\'Shirts\', \'Sweaters\',\'Sweatshirts\',\'T-Shirts\' ) THEN CASE size_unpivot WHEN \'RPL_UNITS_XS\' THEN \'XS\' WHEN \'RPL_UNITS_S\' THEN \'S\' WHEN \'RPL_UNITS_M\' THEN \'M\' WHEN \'RPL_UNITS_L\' THEN \'L\' WHEN \'RPL_UNITS_XL\' THEN \'XL\' WHEN \'RPL_UNITS_XXL\' THEN \'XXL\' WHEN \'RPL_UNITS_3XL\' THEN \'3XL\' WHEN \'RPL_UNITS_4XL\' THEN \'4XL\' WHEN \'RPL_UNITS_5XL\' THEN \'5XL\' WHEN \'RPL_UNITS_6XL\' THEN \'6XL\' END WHEN category IN ( \'Cargo Pants\',\'Jeans\',\'Joggers & Trackpants\',\'Shorts\',\'Trousers\' ) THEN CASE size_unpivot WHEN \'RPL_UNITS_XS\' THEN \'28\' WHEN \'RPL_UNITS_S\' THEN \'30\' WHEN \'RPL_UNITS_M\' THEN \'32\' WHEN \'RPL_UNITS_L\' THEN \'34\' WHEN \'RPL_UNITS_XL\' THEN \'36\' WHEN \'RPL_UNITS_XXL\' THEN \'38\' WHEN \'RPL_UNITS_3XL\' THEN \'40\' WHEN \'RPL_UNITS_4XL\' THEN \'42\' WHEN \'RPL_UNITS_5XL\' THEN \'44\' WHEN \'RPL_UNITS_6XL\' THEN \'46\' END ELSE NULL END AS sizes_mapped, CONCAT( sku_group, \'-\', CASE WHEN category IN ( \'Blazers\',\'Hoodies\',\'Jackets\',\'Overshirt\',\'Shirts\', \'Sweaters\',\'Sweatshirts\',\'T-Shirts\' ) THEN CASE size_unpivot WHEN \'RPL_UNITS_XS\' THEN \'XS\' WHEN \'RPL_UNITS_S\' THEN \'S\' WHEN \'RPL_UNITS_M\' THEN \'M\' WHEN \'RPL_UNITS_L\' THEN \'L\' WHEN \'RPL_UNITS_XL\' THEN \'XL\' WHEN \'RPL_UNITS_XXL\' THEN \'XXL\' WHEN \'RPL_UNITS_3XL\' THEN \'3XL\' WHEN \'RPL_UNITS_4XL\' THEN \'4XL\' WHEN \'RPL_UNITS_5XL\' THEN \'5XL\' WHEN \'RPL_UNITS_6XL\' THEN \'6XL\' END WHEN category IN ( \'Cargo Pants\',\'Jeans\',\'Joggers & Trackpants\',\'Shorts\',\'Trousers\' ) THEN CASE size_unpivot WHEN \'RPL_UNITS_XS\' THEN \'28\' WHEN \'RPL_UNITS_S\' THEN \'30\' WHEN \'RPL_UNITS_M\' THEN \'32\' WHEN \'RPL_UNITS_L\' THEN \'34\' WHEN \'RPL_UNITS_XL\' THEN \'36\' WHEN \'RPL_UNITS_XXL\' THEN \'38\' WHEN \'RPL_UNITS_3XL\' THEN \'40\' WHEN \'RPL_UNITS_4XL\' THEN \'42\' WHEN \'RPL_UNITS_5XL\' THEN \'44\' WHEN \'RPL_UNITS_6XL\' THEN \'46\' END ELSE NULL END ) AS sku, replen_units, final_rank FROM unpivoted ), raw_output AS ( SELECT branch_code, zone, sku_group, category, AVG_SKU_SELL_THRU, sku, sizes_mapped, replen_units, final_rank FROM mapped WHERE replen_units > 0 ), warehouse_inv AS ( SELECT sku, facility, (units_on_hand - 1) AS units_on_hand FROM SNITCH_DB.MAPLEMONK.LIVE_INV_WAREHOUSE_offline_replen WHERE UNITS_ON_HAND > 0 ), inv_mapped AS ( SELECT sku, facility, units_on_hand, CASE WHEN facility = \'SAPL-NORTH-TAURU\' THEN \'NORTH\' WHEN facility IN (\'SAPL-WH1\',\'SAPL-WH2\') THEN \'SOUTH\' ELSE NULL END AS inv_zone FROM warehouse_inv WHERE facility IN (\'SAPL-NORTH-TAURU\',\'SAPL-WH1\',\'SAPL-WH2\') ), inv_tot AS ( SELECT inv_zone AS zone, sku, SUM(units_on_hand) AS total_inv FROM inv_mapped WHERE inv_zone IS NOT NULL GROUP BY 1,2 ), demand AS ( SELECT branch_code, UPPER(zone) AS zone, sku_group, sku, sizes_mapped, AVG_SKU_SELL_THRU, final_rank, ROUND(replen_units, 0) AS replen_units FROM raw_output WHERE UPPER(zone) IN (\'NORTH\',\'SOUTH\') ), demand_with_pool_alloc AS ( SELECT d.*, COALESCE(i.total_inv, 0) AS total_inv, SUM(d.replen_units) OVER ( PARTITION BY d.zone, d.sku ORDER BY d.final_rank ASC, d.AVG_SKU_SELL_THRU DESC, d.branch_code ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_demand FROM demand d LEFT JOIN inv_tot i ON i.zone = d.zone AND i.sku = d.sku ), pool_alloc AS ( SELECT *, (cum_demand - replen_units) AS prev_cum_demand, GREATEST( LEAST(replen_units, total_inv - (cum_demand - replen_units)), 0 ) AS allocated_pool_units FROM demand_with_pool_alloc ), alloc_ranges AS ( SELECT p.*, SUM(allocated_pool_units) OVER ( PARTITION BY zone, sku ORDER BY final_rank ASC, AVG_SKU_SELL_THRU DESC, branch_code ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_alloc, ( SUM(allocated_pool_units) OVER ( PARTITION BY zone, sku ORDER BY final_rank ASC, AVG_SKU_SELL_THRU DESC, branch_code ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) - allocated_pool_units ) AS prev_cum_alloc FROM pool_alloc p WHERE allocated_pool_units > 0 ), facility_units AS ( SELECT inv_zone AS zone, sku, facility, SUM(units_on_hand) AS facility_inv FROM inv_mapped WHERE inv_zone IS NOT NULL GROUP BY 1,2,3 ), facility_priority_base AS ( SELECT f.*, CASE WHEN zone = \'NORTH\' THEN 1 WHEN zone = \'SOUTH\' THEN ROW_NUMBER() OVER ( PARTITION BY zone, sku ORDER BY facility_inv ASC, facility ) ELSE 99 END AS facility_priority FROM facility_units f ), facility_ranges AS ( SELECT f.*, SUM(facility_inv) OVER ( PARTITION BY zone, sku ORDER BY facility_priority ASC, facility ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS cum_fac_inv, ( SUM(facility_inv) OVER ( PARTITION BY zone, sku ORDER BY facility_priority ASC, facility ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) - facility_inv ) AS prev_cum_fac_inv FROM facility_priority_base f ), final_alloc AS ( SELECT a.branch_code, a.sku_group, a.sku, a.sizes_mapped, a.replen_units, a.zone, a.AVG_SKU_SELL_THRU, a.final_rank, fr.facility, GREATEST( LEAST(a.cum_alloc, fr.cum_fac_inv) - GREATEST(a.prev_cum_alloc + 1, fr.prev_cum_fac_inv + 1) + 1, 0 ) AS allocated_units FROM alloc_ranges a JOIN facility_ranges fr ON fr.zone = a.zone AND fr.sku = a.sku WHERE a.cum_alloc >= (fr.prev_cum_fac_inv + 1) AND (a.prev_cum_alloc + 1) <= fr.cum_fac_inv ), sku_summary AS ( SELECT sku, SUM(replen_units) AS cuml_replen_req, SUM(allocated_units) AS cuml_allo FROM final_alloc GROUP BY sku ), interim_allo AS ( SELECT f.*, s.cuml_replen_req, s.cuml_allo, CASE WHEN s.cuml_allo >= s.cuml_replen_req THEN f.allocated_units ELSE CEIL(s.cuml_allo * f.replen_units / s.cuml_replen_req) END AS interim_allo FROM final_alloc f JOIN sku_summary s ON f.sku = s.sku ), socialistic_allo AS ( SELECT i.*, CASE WHEN SUM(interim_allo) OVER ( PARTITION BY sku ORDER BY final_rank ASC, AVG_SKU_SELL_THRU DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) <= cuml_allo THEN interim_allo ELSE GREATEST( 0, cuml_allo - SUM(interim_allo) OVER ( PARTITION BY sku ORDER BY final_rank ASC, AVG_SKU_SELL_THRU DESC ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING ) ) END AS socialistic_allocated_units FROM interim_allo i ) SELECT branch_code, sku_group, sku, sizes_mapped, AVG_SKU_SELL_THRU, final_rank, replen_units, allocated_units, zone, facility, socialistic_allocated_units FROM socialistic_allo ORDER BY sku, final_rank ASC, AVG_SKU_SELL_THRU DESC, branch_code;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
